from collections import deque

def find_connected_components(grid, value):
    """Find all 4-connected components of a given value"""
    h, w = grid.shape
    visited = np.zeros((h, w), dtype=bool)
    components = []

    for i in range(h):
        for j in range(w):
            if grid[i, j] == value and not visited[i, j]:
                component = [(i, j)]
                queue = deque([(i, j)])
                visited[i, j] = True

                while queue:
                    ci, cj = queue.popleft()
                    for di, dj in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        ni, nj = ci + di, cj + dj
                        if 0 <= ni < h and 0 <= nj < w:
                            if not visited[ni, nj] and grid[ni, nj] == value:
                                visited[ni, nj] = True
                                component.append((ni, nj))
                                queue.append((ni, nj))
                components.append(component)

    return components

